const dateFormatter = new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeStyle: 'short' });
function formatDate(value: string | null) { return value ? dateFormatter.format(new Date(value)) : '—'; }
function statusTone(status: Profile['status']) { return status === 'aktif' ? 'success' : status === 'ditolak' ? 'danger' : status === 'menunggu' ? 'warning' : 'neutral'; }
function statusLabel(status: Profile['status']) { return status === 'aktif' ? 'Aktif' : status === 'ditolak' ? 'Ditolak' : status === 'menunggu' ? 'Menunggu' : 'Nonaktif'; }
