export function PendingPage() {
  const { profile, signOut, refreshProfile } = useAuth(); const [loading, setLoading] = useState(false); const [message, setMessage] = useState('');
  async function resubmit() { setLoading(true); const { error } = await supabase.rpc('ajukan_ulang'); setLoading(false); if (error) setMessage('Pengajuan ulang belum dapat diproses.'); else { await refreshProfile(); setMessage('Pengajuan ulang berhasil dikirim.'); } }
  const rejected = profile?.status === 'ditolak';
  return <main className="flex min-h-screen items-center justify-center bg-canvas p-5"><Card className="w-full max-w-lg p-8 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-teal-600/10 text-teal-600"><ShieldCheck className="h-7 w-7" /></div><h1 className="mt-5 text-2xl font-bold text-ink">{rejected ? 'Pendaftaran belum disetujui' : profile?.status === 'nonaktif' ? 'Akun tidak aktif' : 'Menunggu persetujuan'}</h1><p className="mx-auto mt-3 max-w-md leading-relaxed text-muted">{rejected ? 'Silakan periksa alasan dari Super Admin dan ajukan ulang jika sudah diperbaiki.' : profile?.status === 'nonaktif' ? 'Hubungi Super Admin untuk mendapatkan bantuan akses.' : 'Terima kasih sudah mendaftar. Akun Anda sedang ditinjau oleh Super Admin.'}</p>{rejected && profile.reject_reason && <div className="mt-5 rounded-input bg-danger/10 p-4 text-left text-sm text-danger"><strong>Alasan:</strong> {profile.reject_reason}</div>}{message && <p className="mt-4 text-sm font-bold text-teal-900">{message}</p>}<div className="mt-7 flex justify-center gap-3"><Button variant="secondary" onClick={() => void signOut()}>Keluar</Button>{rejected && <Button loading={loading} onClick={() => void resubmit()}>Ajukan ulang</Button>}</div></Card></main>;
}

function Navbar() { const { profile, signOut, pendingCount } = useAuth(); const [open, setOpen] = useState(false); const navigate = useNavigate(); const links = [{ to: '/', label: 'Beranda', icon: LayoutDashboard }, { to: '/surat-masuk', label: 'Surat', icon: FileText }, ...(profile?.role === 'super_admin' ? [{ to: '/persetujuan-akun', label: 'Persetujuan', icon: ShieldCheck }, { to: '/pengguna', label: 'Pengguna', icon: Users }] : [])]; function openPalette() { window.dispatchEvent(new Event('sirama:command-palette')); } const avatarUrl = profile?.avatar_url ? supabase.storage.from('avatars').getPublicUrl(profile.avatar_url).data.publicUrl : null; const initial = profile?.full_name?.slice(0, 1).toUpperCase() || 'A'; return <header className="sticky top-0 z-40 bg-teal-900 text-white shadow-soft"><div className="mx-auto flex h-20 max-w-7xl items-center gap-6 px-5 lg:px-8"><Link to="/" className="flex shrink-0 items-center gap-3"><span className="rounded-input bg-white p-1.5"><img src="/logo-bsi.png" alt="Logo BSI" className="h-8 w-auto" /></span><span className="hidden text-sm font-bold tracking-[0.16em] sm:block">SIRAMA BSI</span></Link><nav className="hidden gap-1 lg:flex lg:flex-row">{links.map(({ to, label, icon: Icon }) => <NavLink key={to} to={to} className={({ isActive }) => `flex items-center gap-2 rounded-input px-3 py-2.5 text-sm font-semibold transition ${isActive ? 'bg-white/15 text-white' : 'text-white/70 hover:bg-white/10 hover:text-white'}`}><Icon className="h-4 w-4" />{label}{label === 'Persetujuan' && pendingCount > 0 && <span className="rounded-full bg-orange px-1.5 py-0.5 text-[10px] text-ink">{pendingCount}</span>}</NavLink>)}</nav><div className="ml-auto flex items-center gap-2"><button onClick={openPalette} className="rounded-input p-2 text-white/70 hover:bg-white/10" aria-label="Cari"><Search className="h-5 w-5" /></button><div className="relative"><button onClick={() => setOpen(!open)} className="flex items-center gap-2 rounded-input p-1.5 hover:bg-white/10">{avatarUrl ? <img src={avatarUrl} alt="Foto profil" className="h-9 w-9 rounded-full object-cover ring-2 ring-white/30" /> : <span className="flex h-9 w-9 items-center justify-center rounded-full bg-teal-600 text-xs font-bold">{initial}</span>}<span className="hidden max-w-28 truncate text-sm font-semibold xl:block">{profile?.full_name || 'Pengguna'}</span><ChevronDown className="hidden h-4 w-4 xl:block" /></button>{open && <div className="absolute right-0 top-12 w-56 rounded-card border border-line bg-white p-2 text-ink shadow-deep"><div className="border-b border-line px-3 py-2"><p className="truncate text-sm font-bold">{profile?.full_name}</p><p className="truncate text-xs text-muted">{profile?.email}</p></div><Link to="/profil" onClick={() => setOpen(false)} className="mt-1 flex w-full items-center gap-2 rounded-input px-3 py-2 text-left text-sm text-ink hover:bg-canvas"><UserCircle className="h-4 w-4" />Profil</Link><button onClick={() => void signOut().then(() => navigate('/login'))} className="mt-1 flex w-full items-center gap-2 rounded-input px-3 py-2 text-left text-sm text-danger hover:bg-danger/10"><LogOut className="h-4 w-4" />Keluar</button></div>}</div></div></div></header>; }

