function BottomNav() { const { profile, pendingCount } = useAuth(); const links = [{ to: '/', label: 'Beranda', icon: LayoutDashboard }, { to: '/surat-masuk', label: 'Surat', icon: FileText }, ...(profile?.role === 'super_admin' ? [{ to: '/persetujuan-akun', label: 'Setuju', icon: ShieldCheck, badge: pendingCount }, { to: '/pengguna', label: 'Pengguna', icon: Users }] : [])]; return <nav className="fixed inset-x-0 bottom-0 z-40 flex items-stretch justify-around border-t border-white/10 bg-teal-900 text-white lg:hidden">{links.map(({ to, label, icon: Icon, badge }) => <NavLink key={to} to={to} className={({ isActive }) => `flex flex-1 flex-col items-center gap-1 py-2 text-[10px] font-semibold transition ${isActive ? 'text-orange' : 'text-white/70'}`}><span className="relative"><Icon className="h-5 w-5" />{Boolean(badge) && <span className="absolute -right-2 -top-1 rounded-full bg-orange px-1 text-[9px] text-ink">{badge}</span>}</span>{label}</NavLink>)}</nav>; }
export function PlaceholderPage({ title, description }: { title: string; description: string }) { return <section><div className="mb-8"><p className="text-sm font-bold uppercase tracking-[0.16em] text-teal-600">SIRAMA BSI</p><h1 className="mt-2 text-3xl font-bold text-ink">{title}</h1><p className="mt-2 text-muted">{description}</p></div><EmptyState title="Ruang kerja Anda siap digunakan" description="Halaman ini akan menampilkan informasi yang relevan saat data mulai tersedia." /></section>; }
