export type Letter = { no: number; id: string; tanggal: string; jenis_surat: string; penerima: string; diterima_oleh: string; approval: 'menunggu' | 'disetujui' | 'ditolak'; approved_by: string | null; approved_at: string | null; keterangan: string | null; lampiran_path: string | null; lampiran_nama: string | null; dibatalkan: boolean; dibatalkan_oleh: string | null; dibatalkan_at: string | null; created_by: string; created_at: string };
type FormValues = { tanggal: string; jenis_surat: string; penerima: string; diterima_oleh: string; keterangan: string };
const letterFields = 'no,id,tanggal,jenis_surat,penerima,diterima_oleh,approval,approved_by,approved_at,keterangan,lampiran_path,lampiran_nama,dibatalkan,dibatalkan_oleh,dibatalkan_at,created_by,created_at';
const maxUploadSize = 10 * 1024 * 1024;
const allowedMime = ['application/pdf', 'image/jpeg', 'image/png', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];
function todayValue() { return new Date().toISOString().slice(0, 10); }
function minDateValue() { const date = new Date(); date.setFullYear(date.getFullYear() - 5); return date.toISOString().slice(0, 10); }
function approvalLabel(approval: Letter['approval']) { return approval === 'disetujui' ? 'Disetujui' : approval === 'ditolak' ? 'Ditolak' : 'Menunggu'; }
function approvalTone(approval: Letter['approval']) { return approval === 'disetujui' ? 'success' : approval === 'ditolak' ? 'danger' : 'warning'; }
function formatBytes(bytes: number) { if (bytes < 1024) return `${bytes} B`; if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`; return `${(bytes / 1024 / 1024).toFixed(1).replace('.', ',')} MB`; }
function extensionOf(name: string) { return name.split('.').pop()?.toLowerCase() ?? ''; }
async function compressImage(file: File) { if (!['image/jpeg', 'image/png'].includes(file.type)) return { file, originalSize: file.size }; const source = await createImageBitmap(file); const scale = Math.min(1, 1600 / Math.max(source.width, source.height)); const canvas = document.createElement('canvas'); canvas.width = Math.round(source.width * scale); canvas.height = Math.round(source.height * scale); canvas.getContext('2d')?.drawImage(source, 0, 0, canvas.width, canvas.height); source.close(); const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.8)); if (!blob) return { file, originalSize: file.size }; return { file: new File([blob], file.name.replace(/\.[^.]+$/, '.jpg'), { type: 'image/jpeg' }), originalSize: file.size }; }
function AttachmentPicker({ selected, onSelect, onClear }: { selected: { file: File; originalSize: number } | null; onSelect: (value: { file: File; originalSize: number }) => void; onClear: () => void }) { const [visible, setVisible] = useState(false); const [error, setError] = useState(''); async function handleFile(file: File | undefined) { if (!file) return; if (!allowedMime.includes(file.type) || file.size > maxUploadSize) { setError('Hanya pdf, jpg, png, docx, atau xlsx dengan ukuran maksimal 10 MB.'); return; } setError(''); onSelect(await compressImage(file)); } function onChange(event: ChangeEvent<HTMLInputElement>) { void handleFile(event.target.files?.[0]); event.target.value = ''; } return <div className="space-y-3"><button type="button" onClick={() => setVisible(!visible)} className="text-sm font-bold text-teal-600 hover:text-teal-900">{visible ? '− Sembunyikan area lampiran' : '+ Lampirkan berkas (opsional)'}</button>{visible && <div className="rounded-card border border-dashed border-line bg-canvas p-4" onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); void handleFile(event.dataTransfer.files[0]); }}><label className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-input border border-line bg-white px-4 py-6 text-center hover:border-teal-600"><UploadCloud className="h-7 w-7 text-teal-600" /><span className="text-sm font-bold text-ink">Seret berkas ke sini atau pilih dari perangkat</span><span className="text-xs text-muted">PDF, JPG, PNG, DOCX, XLSX · Maksimal 10 MB</span><input type="file" accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx" onChange={onChange} className="sr-only" /></label>{error && <p className="mt-3 text-xs text-danger">{error}</p>}{selected && <div className="mt-3 flex items-start justify-between gap-3 rounded-input bg-white p-3"><div className="min-w-0"><p className="truncate text-sm font-bold text-ink">{selected.file.name}</p><p className="mt-1 text-xs text-muted">{formatBytes(selected.originalSize)} menjadi {formatBytes(selected.file.size)}</p></div><button type="button" onClick={onClear} className="shrink-0 text-xs font-bold text-danger">Hapus pilihan</button></div>}</div>}</div>; }
function LetterForm({ initial, existingAttachment, onSubmit, onCancel, loading }: { initial: FormValues; existingAttachment: string | null; onSubmit: (values: FormValues, attachment: { file: File; originalSize: number } | null) => void; onCancel: () => void; loading: boolean }) { const [values, setValues] = useState(initial); const [attachment, setAttachment] = useState<{ file: File; originalSize: number } | null>(null); const [errors, setErrors] = useState<Partial<Record<keyof FormValues, string>>>({}); function update(field: keyof FormValues, value: string) { setValues((current) => ({ ...current, [field]: value })); if (errors[field]) setErrors((current) => ({ ...current, [field]: undefined })); } function submit(event: FormEvent) { event.preventDefault(); const nextErrors: Partial<Record<keyof FormValues, string>> = {}; if (!values.tanggal || values.tanggal > todayValue() || values.tanggal < minDateValue()) nextErrors.tanggal = 'Tanggal harus antara hari ini dan maksimal 5 tahun ke belakang.'; if (!values.jenis_surat.trim()) nextErrors.jenis_surat = 'Jenis surat wajib diisi.'; if (!values.penerima.trim()) nextErrors.penerima = 'Penerima wajib diisi.'; if (!values.diterima_oleh.trim()) nextErrors.diterima_oleh = 'Nama penerima surat wajib diisi.'; setErrors(nextErrors); if (Object.keys(nextErrors).length === 0) onSubmit(values, attachment); } return <form onSubmit={submit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><label className="block space-y-2"><span className="flex items-center gap-1 text-sm font-bold text-ink">Tanggal <span className="text-danger">*</span></span><input type="date" min={minDateValue()} max={todayValue()} value={values.tanggal} onChange={(event) => update('tanggal', event.target.value)} className="h-11 w-full rounded-input border border-line bg-white px-3 text-sm text-ink outline-none focus:border-teal-600 focus:ring-4 focus:ring-teal-600/10" />{errors.tanggal && <span className="text-xs text-danger">{errors.tanggal}</span>}</label><label className="block space-y-2"><span className="flex items-center gap-1 text-sm font-bold text-ink">Jenis surat <span className="text-danger">*</span></span><input value={values.jenis_surat} onChange={(event) => update('jenis_surat', event.target.value)} className="h-11 w-full rounded-input border border-line bg-white px-3 text-sm text-ink outline-none focus:border-teal-600 focus:ring-4 focus:ring-teal-600/10" />{errors.jenis_surat && <span className="text-xs text-danger">{errors.jenis_surat}</span>}</label></div><label className="block space-y-2"><span className="flex items-center gap-1 text-sm font-bold text-ink">Penerima <span className="text-danger">*</span></span><input value={values.penerima} onChange={(event) => update('penerima', event.target.value)} className="h-11 w-full rounded-input border border-line bg-white px-3 text-sm text-ink outline-none focus:border-teal-600 focus:ring-4 focus:ring-teal-600/10" />{errors.penerima && <span className="text-xs text-danger">{errors.penerima}</span>}</label><label className="block space-y-2"><span className="flex items-center gap-1 text-sm font-bold text-ink">Diterima oleh <span className="text-danger">*</span></span><input value={values.diterima_oleh} onChange={(event) => update('diterima_oleh', event.target.value)} className="h-11 w-full rounded-input border border-line bg-white px-3 text-sm text-ink outline-none focus:border-teal-600 focus:ring-4 focus:ring-teal-600/10" />{errors.diterima_oleh && <span className="text-xs text-danger">{errors.diterima_oleh}</span>}</label><label className="block space-y-2"><span className="text-sm font-bold text-ink">Keterangan</span><textarea rows={3} value={values.keterangan} onChange={(event) => update('keterangan', event.target.value)} className="w-full resize-none rounded-input border border-line bg-white p-3 text-sm text-ink outline-none focus:border-teal-600 focus:ring-4 focus:ring-teal-600/10" /></label>{!existingAttachment && <AttachmentPicker selected={attachment} onSelect={setAttachment} onClear={() => setAttachment(null)} />}<div className="flex justify-end gap-3 pt-2"><Button type="button" variant="secondary" onClick={onCancel}>Batal</Button><Button type="submit" loading={loading} variant="accent">Simpan surat</Button></div></form>; }
function LetterTableSkeleton() { return <Card className="overflow-hidden p-5"><div className="space-y-5">{[1, 2, 3, 4, 5].map((item) => <div key={item} className="grid grid-cols-2 gap-4 border-b border-line pb-4 md:grid-cols-6"><Skeleton className="h-5" /><Skeleton className="h-5" /><Skeleton className="h-5" /><Skeleton className="hidden h-5 md:block" /><Skeleton className="hidden h-5 md:block" /><Skeleton className="h-5" /></div>)}</div></Card>; }
export function DetailPanel({ letter, isSuperAdmin, onClose, onEdit, onCancel, onApproval, onDownload, onRemoveAttachment }: { letter: Letter; isSuperAdmin: boolean; onClose: () => void; onEdit: () => void; onCancel: () => void; onApproval: (approval: Letter['approval']) => void; onDownload: () => void; onRemoveAttachment: () => void }) { const [previewUrl, setPreviewUrl] = useState(''); useEffect(() => { let active = true; if (letter.lampiran_path && ['pdf', 'jpg', 'jpeg', 'png'].includes(extensionOf(letter.lampiran_nama ?? ''))) { supabase.storage.from('lampiran').createSignedUrl(letter.lampiran_path, 60).then(({ data }) => { if (active) setPreviewUrl(data?.signedUrl ?? ''); }); } return () => { active = false; }; }, [letter]); const image = ['jpg', 'jpeg', 'png'].includes(extensionOf(letter.lampiran_nama ?? '')); const pdf = extensionOf(letter.lampiran_nama ?? '') === 'pdf'; return <AnimatePresence><div className="fixed inset-0 z-40 bg-teal-900/25 backdrop-blur-sm" onClick={onClose}><m.aside variants={rightPanelVariants} initial="initial" animate="animate" exit="initial" onClick={(event) => event.stopPropagation()} className="absolute right-0 top-0 h-full w-full max-w-xl overflow-y-auto bg-white p-6 shadow-deep max-md:p-4"><div className="flex items-center justify-between border-b border-line pb-5"><div><p className="text-sm font-bold uppercase tracking-wide text-teal-600">Detail surat</p><h2 className="mt-1 text-2xl font-bold text-ink">Surat #{letter.no}</h2></div><button onClick={onClose} aria-label="Tutup detail" className="rounded-full p-2 text-muted hover:bg-canvas"><X className="h-5 w-5" /></button></div><div className="mt-6 space-y-5"><div className="flex items-center justify-between"><Badge tone={letter.dibatalkan ? 'neutral' : approvalTone(letter.approval)}>{letter.dibatalkan ? 'Dibatalkan' : approvalLabel(letter.approval)}</Badge><span className="text-sm text-muted">{letter.tanggal}</span></div><dl className="grid gap-4 rounded-card bg-canvas p-4 sm:grid-cols-2"><div><dt className="text-xs font-bold uppercase tracking-wide text-muted">Jenis surat</dt><dd className="mt-1 font-semibold text-ink">{letter.jenis_surat}</dd></div><div><dt className="text-xs font-bold uppercase tracking-wide text-muted">Penerima</dt><dd className="mt-1 font-semibold text-ink">{letter.penerima}</dd></div><div><dt className="text-xs font-bold uppercase tracking-wide text-muted">Diterima oleh</dt><dd className="mt-1 font-semibold text-ink">{letter.diterima_oleh}</dd></div><div><dt className="text-xs font-bold uppercase tracking-wide text-muted">Dibuat pada</dt><dd className="mt-1 font-semibold text-ink">{formatDate(letter.created_at)}</dd></div></dl><div><h3 className="text-sm font-bold text-ink">Keterangan</h3><p className="mt-2 whitespace-pre-wrap text-sm leading-relaxed text-muted">{letter.keterangan || 'Tidak ada keterangan.'}</p></div><div><h3 className="text-sm font-bold text-ink">Lampiran</h3>{letter.lampiran_path && letter.lampiran_nama ? <div className="mt-3 space-y-3">{pdf && previewUrl && <iframe title="Pratinjau lampiran PDF" src={previewUrl} className="h-72 w-full rounded-input border border-line" />}{image && previewUrl && <img src={previewUrl} alt={letter.lampiran_nama} className="max-h-72 w-full rounded-input border border-line object-contain" />}{!pdf && !image && <div className="rounded-input bg-warning/10 p-4 text-sm text-warning">File ini tidak dapat dipratinjau. Silakan unduh untuk melihatnya.</div>}<div className="flex flex-wrap items-center gap-3"><button onClick={onDownload} className="inline-flex items-center gap-2 text-sm font-bold text-teal-600 hover:text-teal-900"><Download className="h-4 w-4" />Unduh {letter.lampiran_nama}</button>{isSuperAdmin && <button onClick={onRemoveAttachment} className="text-sm font-bold text-danger">Hapus lampiran</button>}</div></div> : <p className="mt-2 text-sm text-muted">Tidak ada lampiran.</p>}</div><div className="border-t border-line pt-5"><label className="block space-y-2"><span className="text-sm font-bold text-ink">Ubah approval</span><select disabled={letter.dibatalkan} value={letter.approval} onChange={(event) => onApproval(event.target.value as Letter['approval'])} className="h-11 w-full rounded-input border border-line bg-white px-3 text-sm text-ink outline-none focus:border-teal-600 focus:ring-4 focus:ring-teal-600/10"><option value="menunggu">Menunggu</option><option value="disetujui">Disetujui</option><option value="ditolak">Ditolak</option></select></label><div className="mt-4 flex flex-wrap gap-3"><Button variant="secondary" onClick={onEdit} disabled={letter.dibatalkan}>Edit</Button>{isSuperAdmin && !letter.dibatalkan && <Button variant="danger" onClick={onCancel}>Batalkan surat</Button>}</div></div></div></m.aside></div></AnimatePresence>; }
export function SuratPage() { const { profile } = useAuth(); const [params, setParams] = useSearchParams(); const status = (params.get('status') ?? 'semua') as 'semua' | Letter['approval']; const [letters, setLetters] = useState<Letter[]>([]); const [allLetters, setAllLetters] = useState<Letter[]>([]); const [counts, setCounts] = useState({ semua: 0, menunggu: 0, disetujui: 0, ditolak: 0 }); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(true); const [failed, setFailed] = useState(false); const [query, setQuery] = useState(''); const [debouncedQuery, setDebouncedQuery] = useState(''); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const [selected, setSelected] = useState<Letter | null>(null); const [modal, setModal] = useState<'add' | 'edit' | null>(null); const [cancelTarget, setCancelTarget] = useState<Letter | null>(null); const [removeTarget, setRemoveTarget] = useState(false); const [saving, setSaving] = useState(false); const [exporting, setExporting] = useState(false); const [view, setView] = useState<'tabel' | 'papan'>('tabel'); const [toast, setToast] = useState(''); const [undoToast, setUndoToast] = useState<{ message: string; id: string; previous: Letter['approval'] } | null>(null);
  async function exportToExcel() { setExporting(true); let request = supabase.from('surat_masuk').select(letterFields).order('tanggal', { ascending: false }).order('no', { ascending: false }); if (status !== 'semua') request = request.eq('approval', status); if (debouncedQuery) request = request.or(`jenis_surat.ilike.%${debouncedQuery}%,penerima.ilike.%${debouncedQuery}%,diterima_oleh.ilike.%${debouncedQuery}%`); if (from) request = request.gte('tanggal', from); if (to) request = request.lte('tanggal', to); const { data, error } = await request; setExporting(false); if (error) { showToast('Ekspor Excel belum dapat diproses.'); return; } if (!data || data.length === 0) { showToast('Tidak ada surat untuk diekspor.'); return; } await exportLettersToExcel(data as Letter[], { status, query: debouncedQuery, from, to }); showToast('Berkas Excel berhasil diunduh.'); }
  useEffect(() => { const timer = window.setTimeout(() => setDebouncedQuery(query), 300); return () => window.clearTimeout(timer); }, [query]);
  const load = useCallback(async () => { setLoading(true); setFailed(false); let request = supabase.from('surat_masuk').select(letterFields, { count: 'exact' }).order('tanggal', { ascending: false }).order('no', { ascending: false }).range((page - 1) * 10, page * 10 - 1); if (status !== 'semua') request = request.eq('approval', status); if (debouncedQuery) request = request.or(`jenis_surat.ilike.%${debouncedQuery}%,penerima.ilike.%${debouncedQuery}%,diterima_oleh.ilike.%${debouncedQuery}%`); if (from) request = request.gte('tanggal', from); if (to) request = request.lte('tanggal', to); const countQuery = (value: 'menunggu' | 'disetujui' | 'ditolak') => { let countRequest = supabase.from('surat_masuk').select('id', { count: 'exact', head: true }).eq('approval', value); if (from) countRequest = countRequest.gte('tanggal', from); if (to) countRequest = countRequest.lte('tanggal', to); return countRequest; }; const [{ data, error, count }, all, waiting, approved, rejected] = await Promise.all([request, supabase.from('surat_masuk').select('id', { count: 'exact', head: true }), countQuery('menunggu'), countQuery('disetujui'), countQuery('ditolak')]); setLoading(false); if (error) { setFailed(true); return; } setLetters((data ?? []) as Letter[]); setTotal(count ?? 0); setCounts({ semua: all.count ?? 0, menunggu: waiting.count ?? 0, disetujui: approved.count ?? 0, ditolak: rejected.count ?? 0 }); }, [debouncedQuery, from, page, status, to]);
  useEffect(() => { void load(); }, [load]); useEffect(() => { setPage(1); }, [status, debouncedQuery, from, to]); useEffect(() => { function close(event: KeyboardEvent) { if (event.key === 'Escape') { setSelected(null); setModal(null); setCancelTarget(null); } } window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close); }, []);
  const loadAll = useCallback(async () => { const { data, error } = await supabase.from('surat_masuk').select(letterFields).eq('dibatalkan', false).order('tanggal', { ascending: false }).order('no', { ascending: false }); if (error) { setFailed(true); return; } setAllLetters((data ?? []) as Letter[]); }, []);
  useEffect(() => { if (view === 'papan') void loadAll(); }, [view, loadAll]);
  async function handleBoardApproval(id: string, newApproval: Letter['approval'], previous: Letter['approval']) { const { error } = await supabase.rpc('set_approval_surat', { p_id: id, p_approval: newApproval }); if (error) { showToast('Status approval belum dapat diubah.'); return; } await loadAll(); const letter = allLetters.find((l) => l.id === id); if (letter) { setAllLetters((prev) => prev.map((l) => l.id === id ? { ...l, approval: newApproval, approved_by: newApproval === 'menunggu' ? null : profile?.id ?? null, approved_at: newApproval === 'menunggu' ? null : new Date().toISOString() } : l)); } setUndoToast({ message: `Surat dipindahkan ke ${approvalLabel(newApproval)}.`, id, previous }); window.setTimeout(() => setUndoToast(null), 6000); }
  async function undoBoardApproval() { if (!undoToast) return; const { id, previous } = undoToast; const { error } = await supabase.rpc('set_approval_surat', { p_id: id, p_approval: previous }); setUndoToast(null); if (error) { showToast('Urungkan belum dapat diproses.'); return; } await loadAll(); showToast('Perubahan diurungkan.'); }
  function chooseStatus(value: string) { setPage(1); if (value === 'semua') { params.delete('status'); setParams(params); } else setParams({ status: value }); }
  function showToast(message: string) { setToast(message); window.setTimeout(() => setToast(''), 4500); }
  function openAdd() { setModal('add'); }
  function openEdit() { setModal('edit'); }
  async function saveLetter(values: FormValues, chosen: { file: File; originalSize: number } | null) { setSaving(true); let uploadPath: string | null = selected?.lampiran_path ?? null; let uploadName: string | null = selected?.lampiran_nama ?? null; if (chosen && profile) { const ext = extensionOf(chosen.file.name); uploadPath = `${profile.id}/${crypto.randomUUID()}.${ext}`; const upload = await supabase.storage.from('lampiran').upload(uploadPath, chosen.file, { contentType: chosen.file.type, upsert: false }); if (upload.error) { setSaving(false); showToast('Lampiran belum dapat diunggah.'); return; } uploadName = chosen.file.name; } const payload = { ...values, keterangan: values.keterangan || null, lampiran_path: uploadPath, lampiran_nama: uploadName }; const result = modal === 'add' ? await supabase.from('surat_masuk').insert(payload) : selected ? await supabase.from('surat_masuk').update(payload).eq('id', selected.id) : { error: new Error('Surat tidak ditemukan') }; setSaving(false); if (result.error) { showToast('Surat belum dapat disimpan.'); return; } setModal(null); setSelected(null); await load(); showToast(modal === 'add' ? 'Surat berhasil ditambahkan.' : 'Surat berhasil diperbarui.'); }
  async function updateApproval(value: Letter['approval']) { if (!selected) return; const { error } = await supabase.rpc('set_approval_surat', { p_id: selected.id, p_approval: value }); if (error) { showToast('Status approval belum dapat diubah.'); return; } await load(); const next = { ...selected, approval: value, approved_by: value === 'menunggu' ? null : profile?.id ?? null, approved_at: value === 'menunggu' ? null : new Date().toISOString() }; setSelected(next); showToast('Status approval berhasil diperbarui.'); }
  async function cancelLetter() { if (!cancelTarget) return; const { error } = await supabase.rpc('batalkan_surat', { p_id: cancelTarget.id }); setCancelTarget(null); if (error) { showToast('Anda tidak memiliki izin untuk tindakan ini.'); return; } await load(); setSelected(null); showToast('Surat berhasil dibatalkan.'); }
  async function removeAttachment() { if (!selected || !profile || profile.role !== 'super_admin' || !selected.lampiran_path) return; const removed = await supabase.storage.from('lampiran').remove([selected.lampiran_path]); if (removed.error) { showToast('Lampiran belum dapat dihapus.'); return; } const { error } = await supabase.from('surat_masuk').update({ lampiran_path: null, lampiran_nama: null }).eq('id', selected.id); if (error) { showToast('Data lampiran belum dapat diperbarui.'); return; } setRemoveTarget(false); const next = { ...selected, lampiran_path: null, lampiran_nama: null }; setSelected(next); await load(); showToast('Lampiran berhasil dihapus.'); }
  async function downloadAttachment() { if (!selected?.lampiran_path || !selected.lampiran_nama) return; const { data, error } = await supabase.storage.from('lampiran').createSignedUrl(selected.lampiran_path, 60, { download: selected.lampiran_nama }); if (error || !data?.signedUrl) { showToast('Lampiran belum dapat diunduh.'); return; } window.open(data.signedUrl, '_blank', 'noopener,noreferrer'); }
  const initial: FormValues = selected ? { tanggal: selected.tanggal, jenis_surat: selected.jenis_surat, penerima: selected.penerima, diterima_oleh: selected.diterima_oleh, keterangan: selected.keterangan ?? '' } : { tanggal: todayValue(), jenis_surat: '', penerima: '', diterima_oleh: '', keterangan: '' }; const pages = Math.max(1, Math.ceil(total / 10));
  return <section><div className="mb-6 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="text-sm font-bold uppercase tracking-[0.16em] text-teal-600">Administrasi surat</p><h1 className="mt-2 text-3xl font-bold text-ink">Surat Masuk</h1><p className="mt-2 text-muted">Registrasi dan pantau seluruh surat masuk.</p></div><div className="flex gap-3"><Button variant="secondary" loading={exporting} onClick={() => void exportToExcel()}><Download className="h-4 w-4" />Export Excel</Button><Button variant="accent" onClick={openAdd}>+ Tambah Surat</Button></div></div><div className="mb-5 flex flex-col gap-3 rounded-card border border-line bg-white p-4 shadow-soft lg:flex-row lg:items-center"><div className="flex flex-1 items-center gap-2 rounded-input border border-line px-3"><Search className="h-4 w-4 text-muted" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Cari jenis surat, penerima, atau diterima oleh" className="h-10 w-full bg-transparent text-sm text-ink outline-none" /></div><div className="flex flex-wrap items-center gap-2"><label className="flex items-center gap-2 rounded-input border border-line px-3 text-sm text-muted"><CalendarDays className="h-4 w-4" /><input type="date" value={from} max={to || todayValue()} onChange={(event) => setFrom(event.target.value)} className="h-10 bg-transparent text-sm text-ink outline-none" /></label><span className="text-muted">—</span><label className="flex items-center gap-2 rounded-input border border-line px-3 text-sm text-muted"><CalendarDays className="h-4 w-4" /><input type="date" value={to} max={todayValue()} onChange={(event) => setTo(event.target.value)} className="h-10 bg-transparent text-sm text-ink outline-none" /></label><button onClick={() => { setQuery(''); setFrom(''); setTo(''); }} className="inline-flex h-10 items-center gap-2 rounded-input px-3 text-sm font-bold text-muted hover:bg-canvas"><SlidersHorizontal className="h-4 w-4" />Reset</button></div><div className="flex rounded-input border border-line bg-white p-1 shadow-soft"><button onClick={() => setView('tabel')} className={`flex items-center gap-1.5 rounded-input px-3 py-2 text-sm font-bold transition ${view === 'tabel' ? 'bg-teal-900 text-white' : 'text-muted hover:text-ink'}`}><Table2 className="h-4 w-4" />Tabel</button><button onClick={() => setView('papan')} className={`flex items-center gap-1.5 rounded-input px-3 py-2 text-sm font-bold transition ${view === 'papan' ? 'bg-teal-900 text-white' : 'text-muted hover:text-ink'}`}><Trello className="h-4 w-4" />Papan</button></div></div><div className="mb-5 flex flex-wrap gap-2">{(['semua', 'menunggu', 'disetujui', 'ditolak'] as const).map((value) => <button key={value} onClick={() => chooseStatus(value)} className={`rounded-full border px-4 py-2 text-sm font-bold transition ${status === value ? 'border-teal-600 bg-teal-600 text-white' : 'border-line bg-white text-muted hover:border-teal-600 hover:text-teal-900'}`}>{value === 'semua' ? 'Semua' : approvalLabel(value)} <span className="ml-1 opacity-80">{counts[value]}</span></button>)}</div>{view === 'papan' ? (loading ? <LetterTableSkeleton /> : failed ? <GenericError /> : <Suspense fallback={<LetterTableSkeleton />}><BoardView letters={allLetters} onApprovalChange={(id, newApproval, previous) => void handleBoardApproval(id, newApproval, previous)} onCardClick={(letter) => setSelected(letter)} /></Suspense>) : (loading ? <LetterTableSkeleton /> : failed ? <GenericError /> : letters.length === 0 ? <EmptyState title="Belum ada surat masuk" description="Surat baru yang Anda tambahkan akan tampil di sini." action={<Button variant="accent" onClick={openAdd}>Tambah surat</Button>} /> : <Card className="overflow-hidden p-5"><div className="hidden grid-cols-[0.45fr_0.8fr_1.4fr_1fr_1fr_0.9fr_0.3fr] gap-4 border-b border-line pb-3 text-xs font-bold uppercase tracking-wide text-muted lg:grid"><span>No</span><span>Tanggal</span><span>Jenis surat</span><span>Penerima</span><span>Diterima oleh</span><span>Approval</span><span /></div><AnimatePresence initial={false}><m.div variants={listVariants} initial="initial" animate="animate">{letters.map((letter) => <m.button type="button" key={letter.id} variants={itemVariants} onClick={() => setSelected(letter)} className={`grid w-full items-center gap-3 border-b border-line py-4 text-left transition last:border-0 hover:bg-canvas lg:grid-cols-[0.45fr_0.8fr_1.4fr_1fr_1fr_0.9fr_0.3fr] ${letter.dibatalkan ? 'text-muted line-through' : 'text-ink'}`}><span className="font-bold">#{letter.no}</span><span className="text-sm">{letter.tanggal}</span><span className="truncate text-sm font-semibold">{letter.jenis_surat}</span><span className="truncate text-sm">{letter.penerima}</span><span className="truncate text-sm">{letter.diterima_oleh}</span><span className="no-underline">{letter.dibatalkan ? <Badge tone="neutral">Dibatalkan</Badge> : <Badge tone={approvalTone(letter.approval)}>{approvalLabel(letter.approval)}</Badge>}</span><span className="no-underline">{letter.lampiran_path && <Paperclip className="h-4 w-4 text-teal-600" />}</span></m.button>)}</m.div></AnimatePresence><div className="mt-5 flex items-center justify-between border-t border-line pt-4 text-sm text-muted"><span>{total} surat</span><div className="flex items-center gap-2"><button disabled={page <= 1} onClick={() => setPage(page - 1)} className="rounded-input border border-line p-2 disabled:opacity-40"><ChevronLeft className="h-4 w-4" /></button><span>Halaman {page} dari {pages}</span><button disabled={page >= pages} onClick={() => setPage(page + 1)} className="rounded-input border border-line p-2 disabled:opacity-40"><ChevronRight className="h-4 w-4" /></button></div></div></Card>)}{modal && <Modal open title={modal === 'add' ? 'Tambah Surat' : 'Edit Surat'} onClose={() => setModal(null)}><LetterForm initial={initial} existingAttachment={modal === 'edit' ? selected?.lampiran_path ?? null : null} onSubmit={(values, chosen) => void saveLetter(values, chosen)} onCancel={() => setModal(null)} loading={saving} /></Modal>}{selected && <DetailPanel letter={selected} isSuperAdmin={profile?.role === 'super_admin'} onClose={() => setSelected(null)} onEdit={openEdit} onCancel={() => setCancelTarget(selected)} onApproval={(value) => void updateApproval(value)} onDownload={() => void downloadAttachment()} onRemoveAttachment={() => setRemoveTarget(true)} />}{cancelTarget && <Modal open title="Batalkan surat" onClose={() => setCancelTarget(null)}><p className="leading-relaxed text-muted">Surat <strong className="text-ink">#{cancelTarget.no}</strong> akan ditandai sebagai dibatalkan dan tidak dapat dipulihkan.</p><div className="mt-6 flex justify-end gap-3"><Button variant="secondary" onClick={() => setCancelTarget(null)}>Batal</Button><Button variant="danger" onClick={() => void cancelLetter()}>Batalkan surat</Button></div></Modal>}{removeTarget && <Modal open title="Hapus lampiran" onClose={() => setRemoveTarget(false)}><p className="leading-relaxed text-muted">Lampiran akan dihapus permanen dari penyimpanan.</p><div className="mt-6 flex justify-end gap-3"><Button variant="secondary" onClick={() => setRemoveTarget(false)}>Batal</Button><Button variant="danger" onClick={() => void removeAttachment()}>Hapus lampiran</Button></div></Modal>}{toast && <Toast message={toast} onClose={() => setToast('')} />}{undoToast && <Toast message={undoToast.message} action="Urungkan" onAction={() => void undoBoardApproval()} onClose={() => setUndoToast(null)} />}</section>; }

function AccountSkeleton() { return <Card className="overflow-hidden p-5"><div className="space-y-5">{[1, 2, 3].map((item) => <div key={item} className="grid grid-cols-1 gap-3 border-b border-line pb-5 md:grid-cols-[1.1fr_1.5fr_1fr_auto]"><Skeleton className="h-5" /><Skeleton className="h-5" /><Skeleton className="h-5" /><Skeleton className="h-10 w-40" /></div>)}</div></Card>; }
function AccountRows({ accounts, action, actionLabel, secondaryAction, secondaryLabel, currentUserId }: { accounts: Account[]; action: (account: Account) => void; actionLabel: string; secondaryAction?: (account: Account) => void; secondaryLabel?: string; currentUserId?: string }) { return <AnimatePresence initial={false}><m.div variants={listVariants} initial="initial" animate="animate" className="divide-y divide-line">{accounts.map((account) => <m.div key={account.id} variants={itemVariants} layout className="grid items-center gap-4 py-4 first:pt-0 last:pb-0 md:grid-cols-[1.1fr_1.5fr_1fr_auto]"><div><p className="font-bold text-ink">{account.full_name || 'Tanpa nama'}</p><p className="mt-1 text-xs text-muted md:hidden">{account.email}</p></div><p className="hidden text-sm text-ink md:block">{account.email}</p><p className="text-sm text-muted">{formatDate(account.created_at)}</p><div className="flex flex-wrap justify-start gap-2 md:justify-end">{currentUserId !== account.id && <><Button className="h-10" onClick={() => action(account)}>{actionLabel}</Button>{secondaryAction && <Button variant="danger" className="h-10" onClick={() => secondaryAction(account)}>{secondaryLabel}</Button>}</>}</div></m.div>)}</m.div></AnimatePresence>; }

export function ApprovalPage() { const { profile, refreshPendingCount } = useAuth(); const [tab, setTab] = useState<'menunggu' | 'riwayat'>('menunggu'); const [accounts, setAccounts] = useState<Account[]>([]); const [loading, setLoading] = useState(true); const [failed, setFailed] = useState(false); const [rejectTarget, setRejectTarget] = useState<Account | null>(null); const [reason, setReason] = useState(''); const [busyId, setBusyId] = useState(''); const [toast, setToast] = useState<{ message: string; account: Account; previousStatus: Profile['status'] } | null>(null); const [undoMessage, setUndoMessage] = useState('');
  const load = useCallback(async () => { setLoading(true); setFailed(false); const { data, error } = await supabase.from('profiles').select(accountFields).order('created_at', { ascending: false }); setLoading(false); if (error) { setFailed(true); return; } setAccounts((data ?? []) as Account[]); }, []);
  useEffect(() => { void load(); }, [load]);
  const pending = useMemo(() => accounts.filter((account) => account.status === 'menunggu'), [accounts]); const history = useMemo(() => accounts.filter((account) => account.status !== 'menunggu'), [accounts]);
  async function changeStatus(account: Account, status: 'aktif' | 'ditolak', rejectReason?: string) { setBusyId(account.id); const { error } = await supabase.rpc('set_status_akun', { p_user_id: account.id, p_status_baru: status, p_alasan: rejectReason ?? null }); setBusyId(''); if (error) { setUndoMessage('Aksi belum dapat diproses.'); return; } setRejectTarget(null); setReason(''); await load(); await refreshPendingCount(); setToast({ message: status === 'aktif' ? 'Akun berhasil disetujui.' : 'Akun berhasil ditolak.', account, previousStatus: account.status }); window.setTimeout(() => setToast(null), 5000); }
  async function undo() { if (!toast) return; const { error } = await supabase.rpc('set_status_akun', { p_user_id: toast.account.id, p_status_baru: 'menunggu', p_alasan: null }); if (error) setUndoMessage('Urungkan belum tersedia karena RPC saat ini belum menerima status menunggu.'); else { setToast(null); await load(); await refreshPendingCount(); } }
  const shown = tab === 'menunggu' ? pending : history;
  return <section><div className="mb-7 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-sm font-bold uppercase tracking-[0.16em] text-teal-600">Administrasi akses</p><h1 className="mt-2 text-3xl font-bold text-ink">Persetujuan Akun</h1><p className="mt-2 text-muted">Tinjau pendaftaran dan kelola keputusan akses pengguna.</p></div><div className="flex rounded-input border border-line bg-white p-1 shadow-soft"><button onClick={() => setTab('menunggu')} className={`rounded-input px-4 py-2 text-sm font-bold ${tab === 'menunggu' ? 'bg-teal-900 text-white' : 'text-muted hover:text-ink'}`}>Menunggu ({pending.length})</button><button onClick={() => setTab('riwayat')} className={`rounded-input px-4 py-2 text-sm font-bold ${tab === 'riwayat' ? 'bg-teal-900 text-white' : 'text-muted hover:text-ink'}`}>Riwayat</button></div></div>{undoMessage && <div className="mb-4 rounded-input bg-warning/10 px-4 py-3 text-sm text-warning">{undoMessage}</div>}{loading ? <AccountSkeleton /> : failed ? <GenericError /> : shown.length === 0 ? <EmptyState title={tab === 'menunggu' ? 'Tidak ada pendaftar yang menunggu' : 'Belum ada riwayat keputusan'} description={tab === 'menunggu' ? 'Semua pendaftaran sudah ditinjau.' : 'Keputusan persetujuan akan muncul di sini.'} /> : <Card className="overflow-hidden p-5"><div className="mb-4 grid grid-cols-1 gap-3 border-b border-line pb-3 text-xs font-bold uppercase tracking-wide text-muted md:grid-cols-[1.1fr_1.5fr_1fr_auto]"><span>Nama</span><span className="hidden md:block">Email</span><span>Waktu daftar</span><span className="hidden md:block">Aksi</span></div>{tab === 'menunggu' ? <AccountRows accounts={shown} currentUserId={profile?.id} action={(account) => void changeStatus(account, 'aktif')} actionLabel={busyId ? 'Memproses' : 'Setujui'} secondaryAction={(account) => setRejectTarget(account)} secondaryLabel="Tolak" /> : <div className="divide-y divide-line">{history.map((account) => <div key={account.id} className="grid items-center gap-4 py-4 first:pt-0 md:grid-cols-[1.1fr_1.5fr_1fr_auto]"><div><p className="font-bold text-ink">{account.full_name || 'Tanpa nama'}</p><p className="mt-1 text-xs text-muted md:hidden">{account.email}</p></div><p className="hidden text-sm text-ink md:block">{account.email}</p><div><Badge tone={statusTone(account.status)}>{statusLabel(account.status)}</Badge><p className="mt-1 text-xs text-muted">{formatDate(account.reviewed_at)}</p></div><p className="text-sm text-muted">{account.reviewed_by ? 'Diputuskan Super Admin' : '—'}</p></div>)}</div>}</Card>}<Modal open={Boolean(rejectTarget)} onClose={() => setRejectTarget(null)} title="Tolak pendaftaran"><p className="text-sm leading-relaxed text-muted">Berikan alasan agar pendaftar memahami keputusan ini. Alasan bersifat opsional.</p><textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={4} placeholder="Tulis alasan penolakan" className="mt-4 w-full resize-none rounded-input border border-line p-3 text-sm text-ink outline-none focus:border-teal-600 focus:ring-4 focus:ring-teal-600/10" /><div className="mt-5 flex justify-end gap-3"><Button variant="secondary" onClick={() => setRejectTarget(null)}>Batal</Button><Button variant="danger" loading={Boolean(rejectTarget && busyId === rejectTarget.id)} onClick={() => rejectTarget && void changeStatus(rejectTarget, 'ditolak', reason)}>Tolak pendaftaran</Button></div></Modal>{toast && <Toast message={toast.message} action="Urungkan" onAction={() => void undo()} onClose={() => setToast(null)} />}</section>;
}

export function UsersPage() { const { profile, refreshPendingCount } = useAuth(); const [accounts, setAccounts] = useState<Account[]>([]); const [query, setQuery] = useState(''); const [loading, setLoading] = useState(true); const [failed, setFailed] = useState(false); const [target, setTarget] = useState<Account | null>(null); const [busy, setBusy] = useState(false); const [message, setMessage] = useState('');
  const load = useCallback(async () => { setLoading(true); setFailed(false); const { data, error } = await supabase.from('profiles').select(accountFields).order('created_at', { ascending: false }); setLoading(false); if (error) setFailed(true); else setAccounts((data ?? []) as Account[]); }, []);
  useEffect(() => { void load(); }, [load]);
  const filtered = useMemo(() => { const normalized = query.trim().toLowerCase(); return accounts.filter((account) => !normalized || account.full_name.toLowerCase().includes(normalized) || account.email.toLowerCase().includes(normalized)); }, [accounts, query]);
  async function updateStatus() { if (!target) return; setBusy(true); const nextStatus = target.status === 'aktif' ? 'nonaktif' : 'aktif'; const { error } = await supabase.rpc('set_status_akun', { p_user_id: target.id, p_status_baru: nextStatus, p_alasan: null }); setBusy(false); if (error) { setMessage('Status pengguna belum dapat diubah.'); return; } setTarget(null); setMessage(nextStatus === 'aktif' ? 'Pengguna berhasil diaktifkan.' : 'Pengguna berhasil dinonaktifkan.'); await load(); await refreshPendingCount(); window.setTimeout(() => setMessage(''), 4000); }
  return <section><div className="mb-7 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-sm font-bold uppercase tracking-[0.16em] text-teal-600">Kontrol akses</p><h1 className="mt-2 text-3xl font-bold text-ink">Pengguna</h1><p className="mt-2 text-muted">Lihat status dan kelola akses pengguna SIRAMA BSI.</p></div><div className="flex h-11 w-full items-center gap-2 rounded-input border border-line bg-white px-3 shadow-soft sm:w-72"><Search className="h-4 w-4 text-muted" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Cari nama atau email" className="w-full bg-transparent text-sm text-ink outline-none placeholder:text-muted" /></div></div>{message && <div className="mb-4 rounded-input bg-success/10 px-4 py-3 text-sm text-success">{message}</div>}{loading ? <AccountSkeleton /> : failed ? <GenericError /> : filtered.length === 0 ? <EmptyState title="Pengguna tidak ditemukan" description="Coba gunakan nama atau email yang berbeda." /> : <Card className="overflow-hidden p-5"><div className="mb-4 grid grid-cols-1 gap-3 border-b border-line pb-3 text-xs font-bold uppercase tracking-wide text-muted md:grid-cols-[1.1fr_1.5fr_0.8fr_0.8fr_1fr_auto]"><span>Nama</span><span className="hidden md:block">Email</span><span>Role</span><span>Status</span><span>Waktu daftar</span><span className="hidden md:block">Aksi</span></div><AnimatePresence initial={false}><m.div variants={listVariants} initial="initial" animate="animate">{filtered.map((account) => <m.div key={account.id} variants={itemVariants} className="grid items-center gap-4 border-b border-line py-4 last:border-0 md:grid-cols-[1.1fr_1.5fr_0.8fr_0.8fr_1fr_auto]"><div><p className="font-bold text-ink">{account.full_name || 'Tanpa nama'}</p><p className="mt-1 text-xs text-muted md:hidden">{account.email}</p></div><p className="hidden break-all text-sm text-ink md:block">{account.email}</p><p className="text-sm text-muted">{account.role === 'super_admin' ? 'Super Admin' : 'Admin'}</p><Badge tone={statusTone(account.status)}>{statusLabel(account.status)}</Badge><p className="text-sm text-muted">{formatDate(account.created_at)}</p><div>{profile?.id !== account.id && account.status !== 'menunggu' && <Button variant={account.status === 'aktif' ? 'danger' : 'primary'} className="h-10" onClick={() => setTarget(account)}>{account.status === 'aktif' ? 'Nonaktifkan' : 'Aktifkan'}</Button>}</div></m.div>)}</m.div></AnimatePresence></Card>}<Modal open={Boolean(target)} onClose={() => setTarget(null)} title={target?.status === 'aktif' ? 'Nonaktifkan pengguna' : 'Aktifkan pengguna'}><p className="leading-relaxed text-muted">Anda yakin ingin {target?.status === 'aktif' ? 'menonaktifkan' : 'mengaktifkan'} akses <strong className="text-ink">{target?.full_name}</strong>?</p><div className="mt-6 flex justify-end gap-3"><Button variant="secondary" onClick={() => setTarget(null)}>Batal</Button><Button variant={target?.status === 'aktif' ? 'danger' : 'primary'} loading={busy} onClick={() => void updateStatus()}>{target?.status === 'aktif' ? 'Nonaktifkan' : 'Aktifkan'}</Button></div></Modal></section>;
}
